function esc(value) { return String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[char]); }
function tokenHash(value) { return crypto.createHash('sha256').update(value).digest('hex'); }
function hashPassword(value, salt) { return crypto.scryptSync(value, salt, 64, { N:16384, r:8, p:1 }).toString('hex'); }
function timingEqualHex(left, right) { const a=Buffer.from(left,'hex'), b=Buffer.from(right,'hex'); return a.length === b.length && crypto.timingSafeEqual(a,b); }
