  if (role === 'admin' || role === 'manager') return { sql: tenantSql, values: [tenantId] };
  const userIndex = startIndex + 1;
  return {
    sql: `(${tenantSql} and (c.assigned_user_id=$${userIndex} or exists(select 1 from queue_members qm join queues aq on aq.id=qm.queue_id and aq.active where qm.queue_id=c.queue_id and qm.user_id=$${userIndex} and qm.active) or exists(select 1 from queues aq join teams t on t.id=aq.team_id and t.active join team_members tm on tm.team_id=t.id and tm.active where aq.id=c.queue_id and aq.active and tm.user_id=$${userIndex})))`,
    values: [tenantId, userId],
  };
