async function loadSystemStatus() {
  const [db, outbox, webhooks, workers, deadLetters, alerts] = await Promise.all([
    pool.query('select 1 ok'),
    pool.query("select coalesce(extract(epoch from now()-min(case when status in ('pending','failed') then available_at end)),0)::int max_age_seconds, count(case when status in ('pending','failed') then 1 end)::int retry_count from outbox_jobs"),
    pool.query("select coalesce(extract(epoch from now()-min(case when status in ('pending','failed') then available_at end)),0)::int max_age_seconds from webhook_events"),
    pool.query("select coalesce(worker_name,worker_id) as worker,extract(epoch from now()-coalesce(updated_at,now()))::int age_seconds,coalesce(status,'active') status from worker_heartbeats"),
    pool.query("select count(*)::int count from outbox_jobs where status='dead_letter'"),
    pool.query("select id,rule_id,severity,status,observed_value from alert_instances where status in ('open','acknowledged','escalated') order by opened_at desc limit 50"),
  ]);
  const { evaluateSystemStatus } = require('./modules/operations/system-status');
  const status = evaluateSystemStatus({ database: Boolean(db.rows[0]?.ok), outboxAgeSeconds: outbox.rows[0]?.max_age_seconds, webhookAgeSeconds: webhooks.rows[0]?.max_age_seconds, workers: workers.rows, retryCount: outbox.rows[0]?.retry_count, deadLetterCount: deadLetters.rows[0]?.count, release: process.env.RELEASE_ID || 'runtime' });
  return { status, alerts: alerts.rows };
}

async function readinessSnapshot(traceId) {
  try {
    const health = await healthSnapshot(traceId);
    return { ...health, status: health.ok ? 'ok' : 'degraded' };
  } catch {
    return { ok: false, db: false, brand: cfg.brand, traceId, readiness: {}, status: 'degraded', statusCode: 503 };
  }
}

